/* ── 탭 전환 ── */
function switchTab(id, btn) {
  document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
  document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
  document.getElementById('tab-' + id).classList.add('active');
  if(btn) btn.classList.add('active');
  window.scrollTo({top: document.querySelector('.tabs-wrap').offsetTop - 10, behavior:'smooth'});
}

/* ── 자원 연계 서식: 섹션 이동 ── */
function icScrollTo(selector) {
  const el = document.querySelector(selector);
  if (!el) return;
  el.scrollIntoView({behavior:'smooth', block:'center'});
  el.classList.add('ref-flash');
  setTimeout(() => el.classList.remove('ref-flash'), 1400);
}

function icToggleDetail(contEl, detailId) {
  const detail = document.getElementById(detailId);
  if (!detail) return;
  detail.classList.toggle('open');
  contEl.querySelector('.ref-caret').classList.toggle('open');
}

/* ── 모달 데이터 ── */

function openModal(key) {
  const d = modals[key]; if(!d) return;
  document.getElementById('mTitle').textContent = d.title;
  document.getElementById('mSub').textContent = d.sub;
  document.getElementById('mBody').innerHTML = d.body;
  document.getElementById('modalOverlay').classList.add('open');
  document.body.style.overflow = 'hidden';
}
function closeModal() { document.getElementById('modalOverlay').classList.remove('open'); document.body.style.overflow = ''; }
function closeModalOnBg(e) { if(e.target===document.getElementById('modalOverlay')) closeModal(); }

/* 지역 선택 지도 (헤더) — 실제 행정구역 SVG 지도 + 팝업 */
function renderKrMap(){
  document.querySelectorAll('.region-map-svg').forEach(svg => {
    if(!svg.dataset.filled){
      svg.innerHTML = KR_MAP_PATHS;
      svg.dataset.filled = '1';
    }
  });
}
function toggleRegionPanel(e){
  if(e) e.stopPropagation();
  const overlay = document.getElementById('regionPanelOverlay');
  if(!overlay) return;
  const open = overlay.classList.contains('open');
  if(open){
    overlay.classList.remove('open');
    document.body.style.overflow = '';
  } else {
    renderKrMap();
    overlay.classList.add('open');
    document.body.style.overflow = 'hidden';
  }
}
function closeRegionPanelOnBg(e){
  if(e.target === document.getElementById('regionPanelOverlay')) toggleRegionPanel();
}
function pickRegion(name, ready, url){
  if(url){
    window.location.href = url;
    return;
  }
  const t = document.getElementById('regionToast');
  if(!t) return;
  if(ready){
    t.className = 'region-toast ok';
    t.textContent = '✅ ' + name + ' — 현재 이용 중인 지역입니다';
  } else {
    t.className = 'region-toast pending';
    t.textContent = '🚧 ' + name + ' — 아직 정보가 없습니다. 준비 중입니다.';
  }
  t.style.display = 'block';
}
document.addEventListener('keydown', e => {
  if(e.key==='Escape'){
    closeModal();
    const overlay = document.getElementById('regionPanelOverlay');
    if(overlay && overlay.classList.contains('open')) toggleRegionPanel();
  }
});

